/**
 * Legacy category type (for backwards compatibility)
 * @deprecated Use provider + secretType instead
 */
export type SecretCategory =
  | 'api-keys'
  | 'database'
  | 'authentication'
  | 'services'
  | 'other';

/**
 * Secret scope distinguishes platform (developer) secrets from user secrets:
 * - platform: Infrastructure-level secrets (SpacetimeDB, Sentry, etc.) - developer only
 * - user: Personal API keys (Alpaca, OpenAI, etc.) - visible to end users
 */
export type SecretScope = 'platform' | 'user';

/**
 * System-level user ID for platform secrets.
 * Platform secrets use this ID instead of individual user IDs so they're
 * accessible to the platform regardless of which user is logged in.
 * These are infrastructure secrets (API keys for data feeds, etc.) managed by admins.
 */
export const PLATFORM_SYSTEM_ID = 'nexus-platform-system';

/**
 * Full secret entry stored in database
 */
export interface Secret {
  /** Unique identifier (UUID) */
  id: string;
  /** Secret name/key (e.g., "ALPACA_API_KEY") */
  key: string;
  /** Owner user ID */
  userId: string;
  /** Encrypted value payload */
  encrypted: EncryptedSecret;
  /** Optional encrypted description */
  encryptedDescription?: EncryptedSecret;
  /** Provider this secret belongs to (e.g., "alpaca", "openai") */
  provider: KnownProvider;
  /** Type of secret (e.g., "api-key", "token", "password") */
  secretType: SecretType;
  /** Legacy category for organization (deprecated, use provider instead) */
  category: SecretCategory;
  /** Scope: platform (developer infrastructure) or user (personal API keys) */
  scope: SecretScope;
  /** Creation timestamp (Unix ms) */
  createdAt: number;
  /** Last update timestamp (Unix ms) */
  updatedAt: number;
  /** Optional expiration timestamp (Unix ms) */
  expiresAt?: number;
  /** Whether synced to cloud (subscriber feature) */
  synced: boolean;
}

/**
 * Secret metadata (without sensitive encrypted values)
 */
export interface SecretMetadata {
  id: string;
  key: string;
  provider: KnownProvider;
  secretType: SecretType;
  category: SecretCategory;
  scope: SecretScope;
  description?: string;
  createdAt: number;
  updatedAt: number;
  expiresAt?: number;
  synced: boolean;
}

/**
 * Options when creating/updating a secret
 */
export interface SecretOptions {
  /** Human-readable description */
  description?: string;
  /** Provider this secret belongs to */
  provider?: KnownProvider;
  /** Type of secret */
  secretType?: SecretType;
  /** Legacy category for organization */
  category?: SecretCategory;
  /** Secret scope (platform or user) - defaults to 'user' */
  scope?: SecretScope;
  /** Optional expiration timestamp */
  expiresAt?: number;
}

// =============================================================================
// SERVICE TYPES
// =============================================================================

/**
 * Secrets service configuration
 */
export interface SecretsServiceConfig {
  /** User ID for scoping secrets */
  userId: string;
  /** Auth token for key derivation */
  authToken: string;
  /** User's subscription tier */
  tier: SecretTier;
  /** Whether to enable cloud sync (subscriber feature) */
  enableCloudSync?: boolean;
}

/**
 * Result of a sync operation
 */
export interface SyncResult {
  /** Whether sync was successful */
  success: boolean;
  /** Number of secrets uploaded to cloud */
  uploaded: number;
  /** Number of secrets downloaded from cloud */
  downloaded: number;
  /** Any conflicts encountered */
  conflicts: SyncConflict[];
  /** Error message if sync failed */
  error?: string;
}

/**
 * Conflict during sync
 */
export interface SyncConflict {
  secretKey: string;
  localUpdatedAt: number;
  remoteUpdatedAt: number;
  resolution: 'local' | 'remote' | 'manual';
}

/**
 * Secret access log entry
 */
export interface SecretAccessLog {
  timestamp: number;
  action: 'read' | 'write' | 'delete' | 'list' | 'export' | 'import';
  secretKey: string;
  source: string;
  success: boolean;
  error?: string;
}

