/**
 * Storage adapter interface for secrets
 */
export interface ISecretsStorageAdapter {
  /** Initialize the adapter */
  initialize(): Promise<void>;

  /** Get a secret by ID */
  get(id: string): Promise<Secret | null>;

  /** Get a secret by key */
  getByKey(userId: string, key: string): Promise<Secret | null>;

  /** Save a secret */
  set(secret: Secret): Promise<void>;

  /** Delete a secret by ID */
  delete(id: string): Promise<void>;

  /** List all secrets for a user */
  list(userId: string): Promise<Secret[]>;

  /** Count secrets for a user */
  count(userId: string): Promise<number>;

  /** Get last sync timestamp */
  getLastSync(): Promise<number>;

  /** Set last sync timestamp */
  setLastSync(timestamp: number): Promise<void>;

  /** Clear all secrets (for logout) */
  clear(): Promise<void>;
}

/**
 * Main secrets service interface
 */
export interface ISecretsService {
  // Lifecycle
  initialize(config: SecretsServiceConfig): Promise<void>;
  isInitialized(): boolean;
  getUserId(): string | null;
  getUserTier(): SecretTier | null;
  lock(): void;

  // CRUD operations
  get(key: string): Promise<string | null>;
  set(key: string, value: string, options?: SecretOptions): Promise<void>;
  delete(key: string): Promise<void>;
  has(key: string): Promise<boolean>;
  list(): Promise<SecretMetadata[]>;

  // Transport helpers (for APIs like Alpaca)
  getBase64(key: string): Promise<string | null>;
  getBasicAuth(keyName: string, secretName: string): Promise<string | null>;

  // Bulk operations
  export(): Promise<Record<string, string>>;
  import(secrets: Record<string, string>, options?: SecretOptions): Promise<void>;

  // Sync (subscriber only)
  sync(): Promise<SyncResult>;
  enableCloudSync(): Promise<void>;
  disableCloudSync(): Promise<void>;
  isCloudSyncEnabled(): boolean;

  // Metadata
  getUsage(): Promise<{ used: number; limit: number }>;
}

