/** Maximum secrets for free tier */
export const FREE_TIER_SECRET_LIMIT = 5;

/** Maximum secrets for pro tier */
export const PRO_TIER_SECRET_LIMIT = 25;

/** Maximum secrets for creator tier */
export const CREATOR_TIER_SECRET_LIMIT = 100;

/** Maximum secrets for team tier */
export const TEAM_TIER_SECRET_LIMIT = 1000;

/** Maximum secrets for admin tier — intentionally 10× team so admins are
 * never gated by the secret cap during platform setup or debugging. */
export const ADMIN_TIER_SECRET_LIMIT = 10000;

/** Legacy: Maximum secrets for subscriber tiers (kept for backwards compatibility) */
export const SUBSCRIBER_SECRET_LIMIT = 1000;

/** All tiers recognised by the secrets service. */
export type SecretTier = 'free' | 'pro' | 'creator' | 'team' | 'admin';

/** Get secret limit for a tier */
export function getSecretLimitForTier(tier: SecretTier): number {
  switch (tier) {
    case 'free':
      return FREE_TIER_SECRET_LIMIT;
    case 'pro':
      return PRO_TIER_SECRET_LIMIT;
    case 'creator':
      return CREATOR_TIER_SECRET_LIMIT;
    case 'team':
      return TEAM_TIER_SECRET_LIMIT;
    case 'admin':
      return ADMIN_TIER_SECRET_LIMIT;
    default:
      return FREE_TIER_SECRET_LIMIT;
  }
}

/** PBKDF2 iterations for key derivation */
export const PBKDF2_ITERATIONS = 100000;

/** Encryption version */
export const ENCRYPTION_VERSION = 1;

/** IndexedDB database name */
export const SECRETS_DB_NAME = 'nexus-secrets';

/** IndexedDB store name */
export const SECRETS_STORE_NAME = 'secrets';

/** IndexedDB store name for bindings */
export const BINDINGS_STORE_NAME = 'secret-bindings';

// =============================================================================
// SECRET BINDING TYPES
// =============================================================================

/**
 * Binding scope determines what the secret is available to:
 * - platform: Available to ALL commands across the entire app
 * - module: Available to all commands within a specific module
 * - command: Available only to a specific command
 */
export type BindingScope = 'platform' | 'module' | 'command';

/**
 * A binding links a secret to a platform, module, or command
 * When a command runs, secrets are resolved in order: platform → module → command
 */
export interface SecretBinding {
  /** Unique binding ID */
  id: string;
  /** User ID for scoping */
  userId: string;
  /** Binding scope level */
  scope: BindingScope;
  /** The command shortcut (only for scope='command') */
  command: string | null;
  /** Module ID (for scope='module' or 'command') */
  moduleId: string | null;
  /** Secret key to inject (from secrets store) */
  secretKey: string;
  /** Environment variable name to inject as (e.g., "API_KEY") */
  envVarName: string;
  /** When binding was created */
  createdAt: number;
  /** When binding was last updated */
  updatedAt: number;
}

/**
 * Metadata for a binding (used in UI)
 */
export interface BindingMetadata {
  id: string;
  scope: BindingScope;
  command: string | null;
  moduleId: string | null;
  secretKey: string;
  envVarName: string;
  createdAt: number;
  updatedAt: number;
}

/**
 * Options when creating a binding
 */
export interface BindingOptions {
  envVarName?: string;
}

/**
 * Storage adapter interface for secret bindings
 */
export interface ISecretBindingsAdapter {
  /** Initialize the adapter */
  initialize(): Promise<void>;

  /** Get all bindings for a user */
  list(userId: string): Promise<SecretBinding[]>;

  /** Get bindings for a specific command (scope='command') */
  getByCommand(userId: string, command: string): Promise<SecretBinding[]>;

  /** Get bindings for a specific module (scope='module') */
  getByModule(userId: string, moduleId: string): Promise<SecretBinding[]>;

  /** Get platform-wide bindings (scope='platform') */
  getPlatformBindings(userId: string): Promise<SecretBinding[]>;

  /** Get a binding by ID */
  get(id: string): Promise<SecretBinding | null>;

  /** Save a binding */
  set(binding: SecretBinding): Promise<void>;

  /** Delete a binding by ID */
  delete(id: string): Promise<void>;

  /** Delete all bindings for a command */
  deleteByCommand(userId: string, command: string): Promise<void>;

  /** Clear all bindings */
  clear(): Promise<void>;
}
